<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityWriteGateway;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Connector\Pdo\PlatformIdentityPdoConnector;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentitySlide;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityCursor;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityFilter;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentityRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentity;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class PlatformIdentityWriteRepositoryAdapter implements PlatformIdentityWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly PlatformIdentityPdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(PlatformIdentityRef $ref): ?PlatformIdentity
    {
        return $this->conn->retrieveForUpdate(new PlatformIdentityFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?PlatformIdentityFilter $filter = null, ?PlatformIdentityCursor $cursor = null): PlatformIdentitySlide
    {
        $this->logDebug("List for update of Platform identity on adapter ");
        $span = $this->startSpan("List for update of Platform identity on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new PlatformIdentitySlide(function (PlatformIdentitySlide $slide, ?PlatformIdentityCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new PlatformIdentityCursor($cursor?->limit() ?? 100, $last->uid ?? null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(PlatformIdentityFilter $filter): ?PlatformIdentity
    {
        $this->logDebug("Retrieve for update of Platform identity on adapter ");
        $span = $this->startSpan("Retrieve for update of Platform identity on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(PlatformIdentityFilter $filter): bool
    {
        $this->logDebug("Exists for update of Platform identity on adapter ");
        $span = $this->startSpan("Exists for update of Platform identity on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?PlatformIdentityFilter $filter = null): int
    {
        $this->logDebug("Count for update of Platform identity on adapter ");
        $span = $this->startSpan("Count for update of Platform identity on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(PlatformIdentity $entity, ?Closure $verify = null): PlatformIdentity
    {
        $this->logDebug("Count for Platform identity on adapter ");
        $span = $this->startSpan("Count for Platform identity on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            \assert($created !== null);
            $this->dispatch($entity);
            $this->changelog->recordChange('platform-identity', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(PlatformIdentityRef $ref, PlatformIdentity $entity): PlatformIdentity
    {
        $this->logDebug("Count for Platform identity on adapter ");
        $span = $this->startSpan("Count for Platform identity on adapter");
        try {
            $updated = $this->conn->update($entity);
            \assert($updated !== null);
            $this->dispatch($entity);
            $this->changelog->recordChange('platform-identity', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(PlatformIdentity $entity): bool
    {
        $this->logDebug("Count for Platform identity on adapter ");
        $span = $this->startSpan("Count for Platform identity on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('platform-identity', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByUid(string $uid): ?PlatformIdentity
    {
        $this->logDebug("Find on by uid for Platform identity on adapter");
        $span = $this->startSpan("Find on by uid for Platform identity on adapter");
        try {
            return $this->conn->retrieveForUpdate(new PlatformIdentityFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(PlatformIdentity $entity): void
    {
        $this->logDebug("Count for Platform identity on adapter ");
        $span = $this->startSpan("Count for Platform identity on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
